module.exports = async (args) => {
  // Output 1 = worth encoding. Output 2 = skip: already encoded by us (hevc_qsv ENCODER tag) or video already <= 8 Mbps.
  const f = args.inputFileObj; const p = f.ffProbeData || {}; const st = p.streams || [];
  const v = st.find((s) => s.codec_type === 'video') || {};
  const enc = JSON.stringify(v.tags || {}) + JSON.stringify((p.format || {}).tags || {});
  if (/hevc_qsv/i.test(enc)) { args.jobLog('Already encoded by Tdarr (hevc_qsv): skip'); return { outputFileObj: f, outputNumber: 2, variables: args.variables }; }
  const total = Number((p.format || {}).bit_rate || 0) / 1000;
  const audio = st.filter((s) => s.codec_type === 'audio').reduce((a, s) => a + Number(s.bit_rate || (s.tags || {}).BPS || (s.tags || {})['BPS-eng'] || 0) / 1000, 0);
  const kbps = total - audio;
  args.jobLog('Video bitrate estimate ' + Math.round(kbps) + ' kbps (total ' + Math.round(total) + ' - audio ' + Math.round(audio) + '), threshold 8000');
  return { outputFileObj: f, outputNumber: kbps > 8000 ? 1 : 2, variables: args.variables };
};

module.exports = async (args) => {
  // Output 1 = new file has the same number of video frames as the original (±0.1%, min 2). Output 2 = frames lost: fail.
  // Catches encodes that ffmpeg reports as successful but that silently lost video (e.g. after a GPU decoder hang).
  const { execFile } = require('child_process');
  const count = (f) => new Promise((res, rej) => execFile('/usr/local/bin/ffprobe',
    ['-v', 'error', '-select_streams', 'v:0', '-count_packets', '-show_entries', 'stream=nb_read_packets', '-of', 'csv=p=0', f],
    { maxBuffer: 1e7 }, (e, out) => (e ? rej(e) : res(parseInt(String(out).trim().replace(/,/g, ''), 10)))));
  const a = await count(args.originalLibraryFile._id);
  const b = await count(args.inputFileObj._id);
  const ok = a > 0 && Math.abs(a - b) <= Math.max(2, a * 0.001);
  args.jobLog('Frame check: original ' + a + ', new ' + b + (ok ? ' OK' : ' -> FRAMES LOST, failing'));
  return { outputFileObj: args.inputFileObj, outputNumber: ok ? 1 : 2, variables: args.variables };
};

