module.exports = async (args) => {
  // Output 1 = encode. Output 2 = skip. Skips: files we already encoded (hevc_qsv ENCODER tag), anything above 1080p
  // (4K has its own flow), AV1/VP9 (already efficient), and HEVC whose video is <= 10 Mbps. Everything else (H.264,
  // MPEG-2, VC-1, high-bitrate HEVC) is encoded.
  const f = args.inputFileObj; const p = f.ffProbeData || {}; const st = p.streams || [];
  const v = st.find((s) => s.codec_type === 'video') || {};
  const skip = (why) => { args.jobLog('Skip: ' + why); return { outputFileObj: f, outputNumber: 2, variables: args.variables }; };
  const enc = JSON.stringify(v.tags || {}) + JSON.stringify((p.format || {}).tags || {});
  if (/hevc_qsv/i.test(enc)) return skip('already encoded by Tdarr (hevc_qsv)');
  if (Number(v.height || 0) > 1088) return skip('above 1080p (' + v.height + 'p), handled by the 4K flow');
  const codec = String(v.codec_name || '').toLowerCase();
  if (['av1', 'vp9'].includes(codec)) return skip(codec + ' is already efficient');
  if (codec === 'hevc') {
    const total = Number((p.format || {}).bit_rate || 0) / 1000;
    const audio = st.filter((s) => s.codec_type === 'audio').reduce((a, s) => a + Number(s.bit_rate || (s.tags || {}).BPS || (s.tags || {})['BPS-eng'] || 0) / 1000, 0);
    const kbps = total - audio;
    args.jobLog('HEVC video bitrate estimate ' + Math.round(kbps) + ' kbps, threshold 10000');
    if (!(kbps > 10000)) return skip('HEVC at or below 10 Mbps');
  }
  args.jobLog('Encode: ' + codec + ' ' + v.height + 'p');
  return { outputFileObj: f, outputNumber: 1, variables: args.variables };
};

