module.exports = async (args) => {
  // Output 1 = video bitrate > 10 Mbps (worth re-encoding), output 2 = already efficient (skip)
  const f = args.inputFileObj; const p = f.ffProbeData || {}; const streams = p.streams || [];
  const v = streams.find((s) => s.codec_type === 'video') || {};
  const tags = v.tags || {};
  let kbps = Number(v.bit_rate || tags.BPS || tags['BPS-eng'] || 0) / 1000;
  if (!kbps) {
    const total = Number((p.format || {}).bit_rate || 0) / 1000;
    const audio = streams.filter((s) => s.codec_type === 'audio')
      .reduce((a, s) => a + Number(s.bit_rate || (s.tags || {}).BPS || (s.tags || {})['BPS-eng'] || 0) / 1000, 0);
    kbps = total - audio;
  }
  args.jobLog('Video bitrate estimate: ' + Math.round(kbps) + ' kbps (threshold 10000)');
  return { outputFileObj: f, outputNumber: kbps > 10000 ? 1 : 2, variables: args.variables };
};
